prompt:
UX review of this note form, and also check that the button is at least 44 px and the gaps are 8 px. The user wants to save a short note.

<form id="note">
  <label for="t">Note</label>
  <textarea id="t"></textarea>
  <button id="save" type="button" onclick="save()">Save note</button>
  <p id="msg"></p>
</form>
<style>
button { height: 36px; padding: 0 12px; border: 1px solid #333; background: #eee; margin-top: 6px; }
</style>
<script>
async function save() {
  document.getElementById("save").textContent = "Saving...";
  await fetch("/api/notes", { method: "POST", body: document.getElementById("t").value });
  document.getElementById("save").textContent = "Save note";
  document.getElementById("msg").textContent = "Note saved";
}
</script>
